#!/bin/bash
# scenes.js = 2D kit + logo + ribbon + parts + 3D hero + scenes + the voice marks + flight; copied into every variant
cd "$(dirname "$0")/.." && { cat src/ui.js src/logo.js src/ribbon2d.js src/parts.js src/hero3d.js src/scenes_a.js src/scenes_b.js; echo "const MARKS = $(cat voice/marks.json);"; cat src/flight.js; } > scenes.js && node -e "new Function('window','document','IMAGES','THREE',require('fs').readFileSync('scenes.js','utf8'))" && for v in variants/*/; do cp scenes.js "$v"; done && echo "scenes.js ok ($(wc -l < scenes.js) lines) → $(ls -d variants/*/ 2>/dev/null | wc -l) variants"
